HTML_PAGE += "<div id=chatPage class=chatPage><div style=background:white;border-bottom:1px solid #E8EAED;padding:12px 20px;display:flex;align-items:center;gap:12px><button onclick=closeChatPage() style=padding:8px 14px;border-radius:20px;border:1px solid #DADCE0;background:white;cursor:pointer>← Dashboard</button><b>Aria Chat</b><div style=margin-left:auto><button onclick=newThread() style=padding:8px 14px;border-radius:20px;background:#1A73E8;color:white;border:none;cursor:pointer>✏️ New thread</button></div></div>"
HTML_PAGE += "<div style=display:flex;flex:1;overflow:hidden><div style=width:280px;background:white;border-right:1px solid #E8EAED;padding:14px;overflow-y:auto;flex-shrink:0><div style=display:flex;gap:8px><input id=chatSearch placeholder=\"Search threads\" style=flex:1;padding:10px;border-radius:20px;border:1px solid #DFE1E5;background:#F1F3F4></div><div style=margin:14px 0><button onclick=newThread() style=width:100%;padding:10px;border-radius:20px;border:1px solid #DADCE0;background:white;cursor:pointer;text-align:left>✏️ New thread</button></div><div style=font-size:12px;color:#5F6368;margin:10px 0>Notebooks</div><div style=padding:8px;cursor:pointer;border-radius:8px>+ Add notebook</div><div style=font-size:12px;color:#5F6368;margin:14px 0 8px>Recent</div><div id=recentList></div></div>"
HTML_PAGE += "<div style=flex:1;display:flex;flex-direction:column;min-width:0><div id=chatMain class=chatMain><div style=text-align:center;color:#5F6368;padding:20px><div style=font-size:28px>👋</div><div style=font-size:16px;margin:8px 0>Good evening, Mahmudul!</div><div>আমাকে কিছু জিজ্ঞেস করো - সহজ বাংলায় উত্তর দিবো</div></div></div><div class=chatInputBar><input id=chatInput placeholder=\"তুমি কেমন আছো? / সহজ বাংলায় শেখাও...\" style=flex:1;padding:12px;border-radius:24px;border:1px solid #DFE1E5;outline:none onkeypress=\"if(event.key==='Enter') sendChat()\"><button onclick=sendChat() class=btnPrimary>Send →</button><button onclick=startVoice() style=width:40px;height:40px;border-radius:50%;border:none;background:conic-gradient(from 0deg,#FBBC05,#EA4335,#34A853,#4285F4,#FBBC05);color:white;cursor:pointer>🎤</button></div></div></div></div>"
HTML_PAGE += "<script>"
HTML_PAGE += "function showComing(name){ alert(name + ' - Coming Soon'); }"
HTML_PAGE += "let avatarState='idle'; let imgA=document.getElementById('imgA');"
HTML_PAGE += "function setAvatarState(s){ avatarState=s; if(!imgA) return; if(s==='idle'){ imgA.style.transform='scale(1) rotate(0deg)'; imgA.style.filter='brightness(1)'; } else if(s==='waving'){ imgA.style.transform='scale(1.03) rotate(1deg)'; setTimeout(()=>{ imgA.style.transform='scale(1) rotate(0deg)'; avatarState='idle'; },900); } else if(s==='explaining'){ imgA.style.transform='scale(1.02) rotate(-1deg)'; setTimeout(()=>{ imgA.style.transform='scale(1) rotate(0deg)'; avatarState='idle'; },1500); } else if(s==='romantic'){ imgA.style.transform='scale(1.02) rotate(2deg)'; setTimeout(()=>{ imgA.style.transform='scale(1) rotate(0deg)'; avatarState='idle'; },2000); } else if(s==='thinking'){ imgA.style.transform='scale(1.01) rotate(-1deg)'; setTimeout(()=>{ imgA.style.transform='scale(1) rotate(0deg)'; avatarState='idle'; },1200); } }"
HTML_PAGE += "setInterval(()=>{ if(avatarState==='idle' && imgA && Math.random()<0.12){ imgA.style.filter='brightness(0.96)'; setTimeout(()=>{ if(imgA) imgA.style.filter='brightness(1)'; },150); } },1000);"
HTML_PAGE += "let threads=[]; try{ threads=JSON.parse(localStorage.getItem('aria_threads')||'[]'); }catch(e){ threads=[]; } if(threads.length===0){ threads=[{title:'তুমি কেমন আছো', msgs:[{role:'user', text:'তুমি কেমন আছো'},{role:'ai', text:'ভালো আছি Mahmudul! তুমি কেমন আছো?'}]}]; } let currentThread=0;"
HTML_PAGE += "function renderRecent(){ const el=document.getElementById('recentList'); if(!el) return; el.innerHTML=''; threads.forEach((t,i)=>{ const d=document.createElement('div'); d.style.cssText='padding:10px;cursor:pointer;border-radius:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis'; d.textContent=t.title; d.onclick=()=>{ currentThread=i; renderChat(); }; if(i===currentThread) d.style.background='#E8F0FE'; el.appendChild(d); }); }"
HTML_PAGE += "function renderChat(){ const main=document.getElementById('chatMain'); if(!main) return; main.innerHTML=''; const th=threads[currentThread]; if(!th || th.msgs.length===0){ main.innerHTML='<div style=text-align:center;color:#5F6368;padding:20px><div style=font-size:28px>👋</div><div>Good evening, Mahmudul!</div><div>আমাকে কিছু জিজ্ঞেস করো</div></div>'; return; } th.msgs.forEach(m=>{ const d=document.createElement('div'); d.className='chatMsg '+(m.role==='user'?'chatUser':'chatAI'); d.innerHTML=(m.role==='user'?'':'<b>Aria:</b> ')+m.text; main.appendChild(d); }); main.scrollTop=main.scrollHeight; }"
HTML_PAGE += "function openChatPage(){ const cp=document.getElementById('chatPage'); cp.style.display='flex'; renderRecent(); renderChat(); setAvatarState('waving'); setTimeout(()=>{ const inp=document.getElementById('chatInput'); if(inp) inp.focus(); },100); }"
HTML_PAGE += "function closeChatPage(){ document.getElementById('chatPage').style.display='none'; setAvatarState('idle'); }"
HTML_PAGE += "function newThread(){ threads.unshift({title:'New thread', msgs:[]}); currentThread=0; localStorage.setItem('aria_threads', JSON.stringify(threads)); renderRecent(); renderChat(); }"
HTML_PAGE += "async function sendChat(){ const inp=document.getElementById('chatInput'); const q=inp.value.trim(); if(!q) return; if(q.toLowerCase().includes('miss you')||q.toLowerCase().includes('love you')||q.includes('মনে পড়ছে')) setAvatarState('romantic'); else if(q.includes('সহজ')) setAvatarState('explaining'); else if(q.includes('course')||q.includes('google')) setAvatarState('waving'); else setAvatarState('thinking'); const th=threads[currentThread]; th.msgs.push({role:'user', text:q}); if(th.msgs.length===1) th.title=q.slice(0,40); localStorage.setItem('aria_threads', JSON.stringify(threads)); renderRecent(); renderChat(); inp.value=''; const main=document.getElementById('chatMain'); const loading=document.createElement('div'); loading.className='chatMsg chatAI'; loading.textContent='⏳ Aria ভাবছে...'; main.appendChild(loading); main.scrollTop=main.scrollHeight; try{ const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:q})}); const data=await res.json(); const cleanText=(data.response||'উত্তর আসেনি'); loading.innerHTML='<b>Aria:</b> '+cleanText; th.msgs.push({role:'ai', text:cleanText}); }catch(e){ loading.innerHTML='<b>Aria:</b> ভালো আছি Mahmudul! তুমি বললে: '+q+' - আমি Aria, সহজ বাংলায় সাহায্য করবো।'; th.msgs.push({role:'ai', text:loading.innerHTML}); } localStorage.setItem('aria_threads', JSON.stringify(threads)); renderRecent(); setAvatarState('idle'); }"
HTML_PAGE += "function startVoice(){ const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR) return alert('Mic not supported'); const rec=new SR(); rec.lang='bn-BD'; rec.start(); rec.onresult=(e)=>{ document.getElementById('chatInput').value=e.results[0][0].transcript; sendChat(); }; }"
HTML_PAGE += "function openCourse(){ document.getElementById('courseOverlay').style.display='block'; setAvatarState('waving'); } function openCourseWith(link){ openCourse(); document.getElementById('courseLink').value=link; } function closeCourse(){ document.getElementById('courseOverlay').style.display='none'; setAvatarState('idle'); }"
HTML_PAGE += "async function parseCourse(){ const link=document.getElementById('courseLink').value.trim(); if(!link) return alert('লিংক দাও'); setAvatarState('explaining'); const resDiv=document.getElementById('courseResult'); resDiv.innerHTML='<div class=card>🔍 '+link+' থেকে Content তুলছি... সহজ বাংলায়</div>'; try{ const resp=await fetch('/api/course',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({link})}); const data=await resp.json(); let html='<div class=card><b>✅ Source: '+data.source+'</b>'; data.modules.forEach((m,i)=>{ html+='<div style=padding:10px;background:#F8F9FA;border-radius:8px;margin:6px 0><b>'+(i+1)+'. '+m.title+'</b><br>'+m.desc+'<br>🎥 '+m.video+'<br>• '+m.points.join(' • ')+'</div>'; }); html+='<div><b>Briefing:</b> '+data.briefing+'</div><div><b>Study Guide:</b> '+data.study_guide+'</div><div><b>Audio:</b> '+data.audio_script+'</div><div><b>FAQ:</b> '+data.faq.join('<br>')+'</div></div>'; resDiv.innerHTML=html; }catch(e){ resDiv.innerHTML='Error: '+e; } setTimeout(()=>setAvatarState('idle'),2000); }"
HTML_PAGE += "document.getElementById('btnBrain').onclick=()=>{ openChatPage(); }; document.getElementById('btnCourse').onclick=()=>{ openCourse(); }; document.getElementById('btnDoodle').onclick=()=>{ alert('Festival: Feb 21, Mar 26, Apr 14, Eid, Durga Puja, Dec 16, Dec 25'); }; document.getElementById('btnMic').onclick=()=>{ openChatPage(); startVoice(); }; renderRecent();"
HTML_PAGE += "const hour=new Date().getHours(); let greet='Good morning'; if(hour>=12&&hour<17) greet='Good afternoon'; else if(hour>=17) greet='Good evening'; document.getElementById('greeting').textContent=greet+', Mahmudul! 👋';"
HTML_PAGE += "</script></body></html>"
